CREATE TYPE public.app_role AS ENUM ('admin','supervisor','representative','student');
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'student', PRIMARY KEY(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, fullname text NOT NULL CHECK(length(fullname) BETWEEN 1 AND 100), email text NOT NULL, member_number text NOT NULL DEFAULT '', requested_role text NOT NULL DEFAULT 'student' CHECK(requested_role IN ('student','supervisor','representative')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'supervisor'));
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.criteria (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), criterion_name text NOT NULL UNIQUE CHECK(length(criterion_name) BETWEEN 1 AND 80), weight numeric NOT NULL CHECK(weight>=0 AND weight<=1));
GRANT SELECT ON public.criteria TO anon,authenticated; GRANT ALL ON public.criteria TO service_role;
ALTER TABLE public.criteria ENABLE ROW LEVEL SECURITY;
CREATE POLICY criteria_read ON public.criteria FOR SELECT USING(true);
CREATE TABLE public.challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 3 AND 150), description text NOT NULL CHECK(length(description) BETWEEN 10 AND 5000), department text NOT NULL, category text NOT NULL, priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN ('Low','Medium','High')), submitted_by uuid, submitter_name text NOT NULL DEFAULT 'Campus community', status text NOT NULL DEFAULT 'Submitted' CHECK(status IN ('Submitted','Under Review','Evaluated','Allocated','In Progress','Completed','Rejected')), weighted_score numeric, recommended boolean NOT NULL DEFAULT false, allocated_to uuid, supervisor_id uuid, feedback text NOT NULL DEFAULT '', supporting_file text, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.challenges TO anon,authenticated; GRANT INSERT ON public.challenges TO authenticated; GRANT ALL ON public.challenges TO service_role;
ALTER TABLE public.challenges ENABLE ROW LEVEL SECURITY;
CREATE POLICY challenge_read ON public.challenges FOR SELECT USING(is_demo OR submitted_by=auth.uid() OR allocated_to=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'supervisor') OR (auth.uid() IS NOT NULL AND status='Evaluated'));
CREATE POLICY challenge_submit ON public.challenges FOR INSERT TO authenticated WITH CHECK(submitted_by=auth.uid() AND NOT is_demo AND status='Submitted' AND weighted_score IS NULL AND allocated_to IS NULL AND supervisor_id IS NULL AND NOT recommended AND public.has_role(auth.uid(),'student'));
CREATE TABLE public.challenge_scores (challenge_id uuid REFERENCES public.challenges(id) ON DELETE CASCADE, criterion_id uuid REFERENCES public.criteria(id), score numeric NOT NULL CHECK(score BETWEEN 1 AND 10), evaluator_id uuid NOT NULL, PRIMARY KEY(challenge_id,criterion_id));
GRANT SELECT ON public.challenge_scores TO authenticated; GRANT ALL ON public.challenge_scores TO service_role;
ALTER TABLE public.challenge_scores ENABLE ROW LEVEL SECURITY;
CREATE POLICY scores_read ON public.challenge_scores FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.challenges c WHERE c.id=challenge_id));
CREATE TABLE public.allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), challenge_id uuid NOT NULL REFERENCES public.challenges(id), allocated_to uuid NOT NULL, supervisor_id uuid NOT NULL, allocation_date timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'Assigned' CHECK(status IN ('Assigned','Accepted','Rejected','Completed')));
GRANT SELECT ON public.allocations TO authenticated; GRANT ALL ON public.allocations TO service_role;
ALTER TABLE public.allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY allocation_read ON public.allocations FOR SELECT TO authenticated USING(allocated_to=auth.uid() OR supervisor_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.progress_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), challenge_id uuid NOT NULL REFERENCES public.challenges(id), user_id uuid NOT NULL, description text NOT NULL CHECK(length(description) BETWEEN 10 AND 3000), evidence_file text, verified boolean NOT NULL DEFAULT false, report_date timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.progress_reports TO authenticated; GRANT ALL ON public.progress_reports TO service_role;
ALTER TABLE public.progress_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_read ON public.progress_reports FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.challenges c WHERE c.id=challenge_id AND c.submitted_by=auth.uid()) OR public.has_role(auth.uid(),'supervisor') OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, action text NOT NULL, timestamp timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, message text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notification_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.create_campus_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,fullname,email,member_number,requested_role) VALUES(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'fullname',''),'Campus member'),100),coalesce(new.email,''),left(coalesce(new.raw_user_meta_data->>'member_number',''),50),CASE WHEN new.raw_user_meta_data->>'requested_role' IN ('student','supervisor','representative') THEN new.raw_user_meta_data->>'requested_role' ELSE 'student' END); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'student'); INSERT INTO public.notifications(user_id,title,message) VALUES(new.id,'Welcome to Campus Challenges','Your account is ready. Staff role requests are reviewed by an administrator.'); RETURN new; END $$;
CREATE TRIGGER campus_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_campus_profile();
CREATE FUNCTION public.log_submission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.submitted_by IS NOT NULL THEN INSERT INTO public.notifications(user_id,title,message) VALUES(new.submitted_by,'Challenge submitted',new.title); INSERT INTO public.audit_logs(user_id,action) VALUES(new.submitted_by,'Submitted challenge: '||new.title); END IF; RETURN new; END $$;
CREATE TRIGGER campus_submission AFTER INSERT ON public.challenges FOR EACH ROW EXECUTE FUNCTION public.log_submission();
CREATE FUNCTION public.campus_action(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); r public.app_role; c public.challenges; a text:=payload->>'action'; cid uuid; item jsonb; total numeric; val numeric; assignee uuid; sup uuid; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT role INTO r FROM public.user_roles WHERE user_id=uid;
IF a='role' THEN IF r<>'admin' THEN RAISE EXCEPTION 'Administrator access required'; END IF; UPDATE public.user_roles SET role=(payload->>'role')::public.app_role WHERE user_id=(payload->>'user_id')::uuid;
ELSIF a='criteria' THEN IF r<>'admin' THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT sum((x->>'weight')::numeric) INTO total FROM jsonb_array_elements(payload->'criteria') x; IF abs(total-1)>0.0001 OR jsonb_array_length(payload->'criteria')<>(SELECT count(*) FROM public.criteria) THEN RAISE EXCEPTION 'Weights must total 100 percent'; END IF; FOR item IN SELECT * FROM jsonb_array_elements(payload->'criteria') LOOP UPDATE public.criteria SET weight=(item->>'weight')::numeric WHERE id=(item->>'id')::uuid; END LOOP; UPDATE public.challenges ch SET weighted_score=(SELECT sum(s.score*cr.weight) FROM public.challenge_scores s JOIN public.criteria cr ON cr.id=s.criterion_id WHERE s.challenge_id=ch.id) WHERE ch.weighted_score IS NOT NULL AND NOT ch.is_demo;
ELSE cid:=(payload->>'challenge_id')::uuid; SELECT * INTO c FROM public.challenges WHERE id=cid FOR UPDATE; IF c.id IS NULL OR c.is_demo THEN RAISE EXCEPTION 'Challenge not editable'; END IF;
IF a='review' THEN IF r NOT IN ('admin','supervisor') OR c.status<>'Submitted' THEN RAISE EXCEPTION 'Cannot review this challenge'; END IF; UPDATE public.challenges SET status='Under Review',feedback=left(coalesce(payload->>'feedback',''),3000) WHERE id=cid;
ELSIF a='score' THEN IF r NOT IN ('admin','supervisor') OR c.status NOT IN ('Submitted','Under Review','Evaluated') THEN RAISE EXCEPTION 'Evaluation not permitted'; END IF; IF jsonb_array_length(payload->'scores')<>(SELECT count(*) FROM public.criteria) THEN RAISE EXCEPTION 'Score every criterion'; END IF; DELETE FROM public.challenge_scores WHERE challenge_id=cid; FOR item IN SELECT * FROM jsonb_array_elements(payload->'scores') LOOP val:=(item->>'score')::numeric; IF val<1 OR val>10 THEN RAISE EXCEPTION 'Scores must be between 1 and 10'; END IF; INSERT INTO public.challenge_scores(challenge_id,criterion_id,score,evaluator_id) VALUES(cid,(item->>'criterion_id')::uuid,val,uid); END LOOP; SELECT sum(s.score*cr.weight) INTO total FROM public.challenge_scores s JOIN public.criteria cr ON cr.id=s.criterion_id WHERE s.challenge_id=cid; UPDATE public.challenges SET weighted_score=total,status='Evaluated',supervisor_id=uid,feedback=left(coalesce(payload->>'feedback',''),3000),recommended=false WHERE id=cid;
ELSIF a='recommend' THEN IF r NOT IN ('admin','supervisor') OR c.status<>'Evaluated' THEN RAISE EXCEPTION 'Evaluate before recommending'; END IF; UPDATE public.challenges SET recommended=true WHERE id=cid;
ELSIF a='allocate' THEN IF r<>'admin' OR c.status<>'Evaluated' OR NOT c.recommended THEN RAISE EXCEPTION 'A recommendation and administrator approval are required'; END IF; assignee:=(payload->>'allocated_to')::uuid; sup:=(payload->>'supervisor_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=assignee AND role IN ('student','representative')) OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=sup AND role='supervisor') THEN RAISE EXCEPTION 'Select an eligible assignee and supervisor'; END IF; INSERT INTO public.allocations(challenge_id,allocated_to,supervisor_id) VALUES(cid,assignee,sup); UPDATE public.challenges SET status='Allocated',allocated_to=assignee,supervisor_id=sup WHERE id=cid; INSERT INTO public.notifications(user_id,title,message) VALUES(assignee,'Challenge allocated',c.title);
ELSIF a='decline_allocation' THEN IF r<>'admin' OR c.status<>'Evaluated' THEN RAISE EXCEPTION 'Not permitted'; END IF; UPDATE public.challenges SET recommended=false,feedback=left(coalesce(payload->>'feedback','Allocation recommendation declined'),3000) WHERE id=cid;
ELSIF a='accept' THEN IF c.allocated_to IS DISTINCT FROM uid OR c.status<>'Allocated' THEN RAISE EXCEPTION 'Only the assigned member may accept'; END IF; UPDATE public.challenges SET status='In Progress' WHERE id=cid; UPDATE public.allocations SET status='Accepted' WHERE challenge_id=cid;
ELSIF a='progress' THEN IF c.allocated_to IS DISTINCT FROM uid OR c.status<>'In Progress' THEN RAISE EXCEPTION 'Only the assigned member can update active work'; END IF; INSERT INTO public.progress_reports(challenge_id,user_id,description,evidence_file) VALUES(cid,uid,payload->>'description',payload->>'evidence_file'); INSERT INTO public.notifications(user_id,title,message) VALUES(c.supervisor_id,'Progress updated',c.title);
ELSIF a='verify' THEN IF r NOT IN ('admin','supervisor') THEN RAISE EXCEPTION 'Supervisor access required'; END IF; UPDATE public.progress_reports SET verified=true WHERE id=(payload->>'report_id')::uuid AND challenge_id=cid;
ELSIF a='complete' THEN IF r NOT IN ('admin','supervisor') OR c.status<>'In Progress' OR NOT EXISTS(SELECT 1 FROM public.progress_reports WHERE challenge_id=cid AND verified) THEN RAISE EXCEPTION 'Verify a progress report before completing'; END IF; UPDATE public.challenges SET status='Completed' WHERE id=cid; UPDATE public.allocations SET status='Completed' WHERE challenge_id=cid; INSERT INTO public.notifications(user_id,title,message) VALUES(c.allocated_to,'Challenge completed',c.title);
ELSIF a='reject' THEN IF r NOT IN ('admin','supervisor') OR c.status NOT IN ('Submitted','Under Review','Evaluated') THEN RAISE EXCEPTION 'Cannot reject this challenge'; END IF; UPDATE public.challenges SET status='Rejected',feedback=left(coalesce(payload->>'feedback',''),3000) WHERE id=cid;
ELSE RAISE EXCEPTION 'Unknown action'; END IF; END IF; INSERT INTO public.audit_logs(user_id,action) VALUES(uid,a||coalesce(': '||c.title,'')); END $$;
REVOKE ALL ON FUNCTION public.campus_action(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.campus_action(jsonb) TO authenticated;
CREATE POLICY evidence_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='challenge-evidence' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY evidence_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='challenge-evidence' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'supervisor')));
CREATE INDEX challenges_submitter ON public.challenges(submitted_by); CREATE INDEX challenges_assignee ON public.challenges(allocated_to); CREATE INDEX progress_challenge ON public.progress_reports(challenge_id); CREATE INDEX notifications_user ON public.notifications(user_id);
